import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController, Platform } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { SidsService } from 'src/app/services/emis/sids.service';
import { UserService } from 'src/app/services/emis/user.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { LoadingService } from 'src/app/services/tnvn/services/loading.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-primary-sids-school',
  templateUrl: './primary-sids-school.page.html',
  styleUrls: ['./primary-sids-school.page.scss'],
})
export class PrimarySidsSchoolPage implements OnInit {

  form: FormGroup;
  schoolInfo: any;
  noData: boolean = true;
  submitted: boolean = false;
  routeData: any;
  Id: any;
  noDataFound: boolean;
  username: any;
  data: any;
  udiseLen: any;
  schoolId: any;
  schoolName: any;
  district: any;
  block: any;
  udise: any;
  sessionUserName: any;
  filter: any[] = [];
  pipe = new DatePipe('en-US');
  dataFound: boolean;
  visitorData: any;
  visitId: any;
  date: any = new Date().getDate()
  year: any = new Date().getFullYear()
  month: any = new Date().getMonth()
  myDate: String = "";
  todayDateFormat: string;
  sessionTypeName: any;
  VisitStatus: any;
  subscription:any;
  VisitStatusLog: any;

  constructor(private fb: FormBuilder, private userService: UserService, private route: ActivatedRoute,
    private router: Router, private alertService: AlertService, private userSessionService: UserSessionService,
    private sqliteDB: SqlitedatabaseService,
    private loadService: LoadingService, private sidsService: SidsService,
    private alertController: AlertController, private platform: Platform
  ) {
    this.username = this.userSessionService.emis_username();
    console.log(this.username, "this.username")
    this.subscription = this.platform.backButton.subscribeWithPriority(9999, () => {});
  }

  ngOnInit() {
    this.initialValidator();
  }

  ionViewDidEnter() {
    this.form.reset()
    this.sessionUserName = this.userSessionService.emis_username();
    this.sessionTypeName = this.userSessionService.emis_usertype();
    this.myDate = this.year + '-' + this.month + '-' + this.date
    this.todayDateFormat = this.pipe.transform(new Date(), 'yyyy-MM-dd');
    this.visitorData = []
    this.schoolInfo = []
   }

  initialValidator() {
    this.form = this.fb.group({
      'udise': new FormControl('', Validators.required),
    });
  }

  getVistorData(id) {
    this.userService.getVisitSids(id).subscribe((res) => {
      this.visitorData = []
      if(res.dataStatus){
        this.visitorData = res.result
        for (let i = 0; i < res.result.length; i++) {
          console.log("visitId",this.visitorData[i].Id)
          this.visitId = this.visitorData[i].Id;
          this.VisitStatus = this.visitorData[i].VisitStatus;
          this.VisitStatusLog = this.visitorData[i].VisitStatusLog;
        }
        if(+this.VisitStatus == 2){
          this.visitId = "";
        }
      }else{
        this.visitId = "";
        this.VisitStatus = "";
      }
      
      console.log("VisitStatus", this.VisitStatus+"    "+"VisitId", this.visitId);
    })
  }

  getSchoolInfo() {
    debugger
    if (this.form.valid) {
      this.userService.getSchoolInfo(this.form.value.udise).subscribe((res) => {
        if (res.dataStatus) {
          this.noData = false;
          this.noDataFound = false;
          this.dataFound = true;
          this.schoolInfo = res.result[0];
          this.userService.udiseCode = this.form.value.udise;
          this.getVistorData(res.result[0].SclId)
        } else {
          this.noData = true;
          this.noDataFound = true;
        }
      });
    } else {
      this.submitted = true;
      this.alertService.error('Invalid UDISE Format');
    }

  }

  getSchoolInfoPost() {
    if (this.form.valid) {
      this.userService.getSchoolInfo(this.form.value.udise).subscribe((res) => {
        if (res.dataStatus) {
          this.noData = false;
          this.noDataFound = false;
          this.dataFound = true;
          this.schoolInfo = res.result[0];
          this.visitorData = []
          this.userService.getVisitSids(res.result[0].SclId).subscribe((res) => {
            this.visitorData = res.result
            for (let i = 0; i < res.result.length; i++) {
              console.log(this.visitorData[i].Id)
              this.visitId = this.visitorData[i].Id;
              this.VisitStatus = this.visitorData[i].VisitStatus;
              this.VisitStatusLog = this.visitorData[i].VisitStatusLog;
            }
            console.log('this.VisitStatus',this.VisitStatus)
            this.router.navigate(['/tabs/primary-dashboard'], { queryParams: { 'schoolId': this.schoolInfo.SclId, 'vistId': this.visitId,'visitstatus':this.VisitStatus, verify : "1" }, skipLocationChange: false });
            // this.router.navigate(['/tabs/home-sids'], { queryParams: { 'schoolId': this.schoolInfo.SclId, 'vistId': this.visitId }, skipLocationChange: false });
          })

        } else {
          this.noData = true;
          this.noDataFound = true;
        }
      });
    } else {
      this.submitted = true;
      this.alertService.error('Invalid UDISE Format');
    }

  }

  goToBack() {
    this.router.navigate(['/tabs/sids-dashboard']);
  }

  nextPage() {
    debugger
    console.log(this.schoolInfo.SclId, "school", this.visitId)
    if(+this.schoolInfo.CattyId == 2 || +this.schoolInfo.CattyId == 3 || +this.schoolInfo.CattyId == 10){
    if (this.visitId) {
      if(!this.VisitStatusLog){
        let params = {
          Id: this.visitId,
          SchlId: this.schoolInfo.SclId
        }
        let data = {
          records: params
        }
        this.sidsService.SchlVisitStatus(data).subscribe((res) => {
          if(res.dataStatus){
            console.log("Responce",res)
          }
        })
      }
      this.router.navigate(['/tabs/primary-dashboard'], { queryParams: { 'schoolId': this.schoolInfo.SclId, 'vistId': this.visitId ,'visitstatus':this.VisitStatus, 'verify' : "1"}, skipLocationChange: false });
      // this.router.navigate(['/tabs/home-sids'], { queryParams: { 'schoolId': this.schoolInfo.SclId, 'vistId': this.visitId }, skipLocationChange: false });
    } else {
      {

        let data = {
          "records": {
            "IndexId": "",
            "SchlId": this.schoolInfo.SclId,
            "VistUId": this.sessionUserName,
            "VistUTy": this.sessionTypeName,
            "VistDate": this.todayDateFormat,
            "VistStas": "1",
            "VistLog": "1",
          }
        }

        this.userService.saveVisitSids(data).subscribe(res => {
          // this.router.navigate(['/tabs/home-sids'], { queryParams: { 'schoolId': this.schoolInfo.SclId, 'vistId': this.visitId }, skipLocationChange: false });
          console.log(res, "data")
          if(res.dataStatus){
            this.getSchoolInfoPost()
          }else{
            this.alertService.error(res.message);
          }
        })
      }

    }
    }else{
      this.alertService.error('Primary and Middle School only allowed');
    }
  }

  onKeypressEvent(event) {
    //debugger
    this.udiseLen = this.form.value.udise;
    let len = this.udiseLen.length;
    if (len == 11) {

    }
    else {
      this.schoolInfo = [];
      this.noData = true;
    }
  }

  ionViewWillLeave(){
    this.dataFound = false;
    this.subscription.unsubscribe();
  }

}
